import{_ as n,o as r,c as t,ag as s}from"./chunks/framework.D5hoimZQ.js";const l=JSON.parse('{"title":"🔬 科学日报 | 2026年10月29日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-10-29.md","filePath":"science-log/src/science-daily/2026-10-29.md"}'),e={name:"science-log/src/science-daily/2026-10-29.md"};function a(g,o,i,d,c,p){return r(),t("div",null,[...o[0]||(o[0]=[s('<h1 id="🔬-科学日报-2026年10月29日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年10月29日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年10月29日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年10月29日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：科学快报 第48期（共 10 条：科学前沿 5 + AI前沿 5） 分析日期：2026-10-29 版本：扩展版（10 条深度 + 交叉关联）</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-首次合成「五元—七元环」碳纳米带-本征金属、近弹道输运" tabindex="-1">1. 首次合成「五元—七元环」碳纳米带：本征金属、近弹道输运 <a class="header-anchor" href="#_1-首次合成「五元—七元环」碳纳米带-本征金属、近弹道输运" aria-label="Permalink to &quot;1. 首次合成「五元—七元环」碳纳米带：本征金属、近弹道输运&quot;">​</a></h3><p><strong>原文</strong>：金属性碳基纳米带是原子级精确的一维导体，理想情况下电导可接近金属碳纳米管（量子极限）。此前金属性石墨烯纳米带靠能带工程（如零模超晶格）实现，但完全非苯环（non-benzenoid）碳同素异形体的原子级精确金属带——如理论预言的碳戊搭烯（carbon pentaheptite）——一直未被做出来。作者用层级式表面合成：先把预合成的聚环辛二烯链转化为排列整齐的聚戊搭烯链，再把这些链侧向融合成平面碳戊搭烯纳米带（CPHN）。两种窄带共用同一基底结构（中央一条七元环链，两侧是同向或异向取向的聚戊搭烯链）：CPHN 1 是本征金属，CPHN 2 是窄带隙半导体。CPHN 1 呈现接近一个电导量子的近弹道电导，可与金属碳纳米管相比。</p><p><strong>深度扩展</strong>：</p><p>金属性碳纳米带一直是「碳基电子学」的圣杯——理论上，其电导可像金属碳纳米管一样逼近一个电导量子 G₀ = 2e²/h。问题在于，已有的金属石墨烯纳米带多靠「能带工程」（外加电场、零模超晶格）而非材料本身的本征金属性。这篇发表于《Nature》（2026 年 10 月 28 日，第 658 卷 8138 期，1176–1182 页）的工作，由 Jianmin Huang、Qitang Fan、Jie Meng、Jia Liu、Jie Cui、Jianing Wang 等完成，用<strong>层级式表面合成（hierarchical on-surface synthesis）<strong>首次把理论预言的</strong>碳戊搭烯（carbon pentaheptite）</strong>——一种完全由五元环与七元环拼接、**不含任何苯环（non-benzenoid）**的碳同素异形体——做成了原子级精确的纳米带（CPHN）。</p><p>方法分两步：① 先把预合成的<strong>聚环辛二烯链</strong>在金属表面转化为排列整齐的<strong>聚戊搭烯链</strong>；② 再让这些链<strong>侧向融合</strong>成平面纳米带。关键数字：两种窄带共用同一基底（中央一条七元环链 + 两侧聚戊搭烯链，取向不同），其中 <strong>CPHN 1 是本征金属</strong>，室温电导接近<strong>一个电导量子</strong>、呈近弹道输运；<strong>CPHN 2 则是窄带隙半导体</strong>。为什么重要：这是「平面碳金属」的第一例，为「碳量子线」——可规模化、可图案化的全碳互连——提供了真实材料基础。</p><p><strong>跨主题关联</strong>：属于 <code>topics/materials/index.md</code>（碳基材料谱系）与 <code>topics/physics/index.md</code>（低维输运）的交汇；作为第48期简讯收录于 <code>topics/science-news/index.md</code>。</p><hr><h3 id="_2-石墨烯的「子周期录像」-直接拍到朗道–齐纳–马约拉纳隧穿" tabindex="-1">2. 石墨烯的「子周期录像」：直接拍到朗道–齐纳–马约拉纳隧穿 <a class="header-anchor" href="#_2-石墨烯的「子周期录像」-直接拍到朗道–齐纳–马约拉纳隧穿" aria-label="Permalink to &quot;2. 石墨烯的「子周期录像」：直接拍到朗道–齐纳–马约拉纳隧穿&quot;">​</a></h3><p><strong>原文</strong>：强光场能全光地裁剪电子的相干轨迹、改写能带乃至塑造物态，但要看懂机制，需要在能带里直接可视化光波驱动的电子运动。此前光电子动量显微只能拍多周期平均的激发电子，子周期能带录像又限于小动量。作者提出阿秒精度、覆盖整个第一布里渊区的子周期能带录像，可视化一种最基础却难捉摸的强场过程——非绝热 Landau–Zener–Majorana（LZM）隧穿：强场在石墨烯类狄拉克能带内的加速与周期性 LZ 带间隧穿相互交织，表现为布里渊区边缘载流子分布的相干子周期位移与畸变。</p><p><strong>深度扩展</strong>：</p><p>强激光场能在飞秒—阿秒尺度上改写电子的相干轨迹、甚至重塑物态，但「看见」电子在能带里被光驱动，一直是实验难题：光电子动量显微只能给出多周期平均图像，而子周期录像又受限于小动量区。这项工作（《Nature》2026 年 10 月 28 日，第 659 卷 8139 期，63–68 页；作者 V. Eggers、G. Inzani、M. Meierhofer、L. Münster、J. Helml、R. Wallauer 等）提出了一种<strong>覆盖整个第一布里渊区、阿秒精度</strong>的「子周期能带录像」。</p><p>它直接可视化了一类最基础却难捉摸的强场过程——<strong>非绝热 Landau–Zener–Majorana（LZM）隧穿</strong>：强场在石墨烯类狄拉克能带内<strong>加速</strong>电子，与<strong>周期性 LZ 带间隧穿</strong>相互交织，表现为布里渊区边缘载流子分布的<strong>相干子周期位移与畸变</strong>。关键突破：这种极端<strong>非热（non-thermal）分布</strong>能把相互竞争的散射过程<strong>分离开</strong>，使作者得以定量评估各散射通道对相干电子控制的影响。为什么重要：它把「强场操控量子材料」从黑箱变成全景显微镜下的动力学问题——为光场驱动的量子态裁剪提供了微观依据。</p><p><strong>跨主题关联</strong>：与 <code>topics/quantum-physics/index.md</code>、<code>topics/physics/index.md</code> 中强场物理/能带动力学笔记勾连——「外场=坐标变换、内禀能带=不变量」的结构与 <code>topics/cross-domain-synthesis-2026-q3.md</code> 的「代码-状态分离」同构。</p><hr><h3 id="_3-硅酮「回到单体」-脱氧氯化把惰性硅氧链直接拆回二氯硅烷" tabindex="-1">3. 硅酮「回到单体」：脱氧氯化把惰性硅氧链直接拆回二氯硅烷 <a class="header-anchor" href="#_3-硅酮「回到单体」-脱氧氯化把惰性硅氧链直接拆回二氯硅烷" aria-label="Permalink to &quot;3. 硅酮「回到单体」：脱氧氯化把惰性硅氧链直接拆回二氯硅烷&quot;">​</a></h3><p><strong>原文</strong>：硅酮因优异的热稳定性和化学惰性被广泛用于工业、医疗与消费品——也正因此，它的化学回收与高值化极其困难。当前的废硅酮处理主要是填埋、焚烧、机械回收、或回环状硅氧烷。作者提出一种硅鎓离子（silylium-ion）引发的解聚策略：用光气的更高级取代物、乃至光气本身作为脱氧氯化试剂，在温和条件下直接切断 Si–O–Si 键，重新生成工业上相关的二氯硅烷单体（闭环式「回料」回收）。</p><p><strong>深度扩展</strong>：</p><p>硅酮（聚硅氧烷）因优异的热稳定性与化学惰性被广泛用于工业、医疗与消费品，但也正因此，其化学回收与高值化极其困难：目前的废硅酮处理主要是<strong>填埋、焚烧、机械回收，或把长链打回环状硅氧烷</strong>，都难算真正的高值闭环。这项发表于《Nature》（2026 年 10 月 28 日）的工作，由 Biping Xu、Tobias Randt、Xiaojie Liu、Zheng-Wang Qu、Stefan Grimme、Hendrik F. T. Klare 等完成（作者组合指向德国波恩一脉的<strong>硅鎓离子化学</strong>传统，Grimme 以 DFT 方法著称），提出了一种<strong>硅鎓离子（silylium-ion）引发</strong>的解聚策略。</p><p>方法：用<strong>光气的更高级取代物、乃至光气本身</strong>作为<strong>脱氧氯化试剂</strong>，在<strong>温和条件</strong>下直接<strong>切断 Si–O–Si 键</strong>，重新生成工业上相关的<strong>二氯硅烷单体</strong>（即「回到单体」闭环回收）。关键点：该法<strong>底物普适性广</strong>，适用线性与环状硅氧烷，包括<strong>商用硅油与弹性体</strong>。机理 + 计算表明，光气并非只当氯源——在<strong>硅鎓离子路易斯酸活化</strong>下，它<strong>原位生成氯羰基阳离子</strong>作为真正的活性切割剂。为什么重要：它为化学惰性的硅氧烷材料提供了一条<strong>可持续循环回收</strong>的新路径——把「难降解」从缺点转为可控的定向断键。</p><p><strong>跨主题关联</strong>：与 <code>topics/materials/index.md</code> 的材料回收/循环经济条目关联；其「用强亲电试剂精确切断惰性键」的逻辑与 <code>topics/cross-domain-synthesis-2026-q3.md</code> 的「约束-涌现」模式呼应。</p><hr><h3 id="_4-心脏的「乳酸捷径」-mct1-把乳酸直接搬进线粒体供能" tabindex="-1">4. 心脏的「乳酸捷径」：MCT1 把乳酸直接搬进线粒体供能 <a class="header-anchor" href="#_4-心脏的「乳酸捷径」-mct1-把乳酸直接搬进线粒体供能" aria-label="Permalink to &quot;4. 心脏的「乳酸捷径」：MCT1 把乳酸直接搬进线粒体供能&quot;">​</a></h3><p><strong>原文</strong>：心脏能灵活氧化葡萄糖、乳酸等多种燃料以应对饮食、运动与损伤应激。传统观点认为糖类氧化都要先走胞质生成丙酮酸、再由线粒体丙酮酸载体（MPC）进入三羧酸（TCA）循环。作者发现，即使遗传敲除 MPC，小鼠心肌仍能氧化葡萄糖来源的碳；这条备用通路依赖单羧酸转运体 MCT1（Slc16a1）。进一步发现，通常定位于质膜的 MCT1 也存在于小鼠与人心肌细胞的线粒体内膜：它与基质中的 LDHB 搭档，在线粒体内把乳酸转成丙酮酸与 NADH，直接给电子传递链供料。</p><p><strong>深度扩展</strong>：</p><p>心脏能灵活氧化葡萄糖、乳酸、脂肪酸等多种燃料以应对饮食、运动与应激。传统教科书认为：糖类氧化都要先在胞质生成<strong>丙酮酸</strong>，再由**线粒体丙酮酸载体（MPC）**运入基质、进入三羧酸（TCA）循环。这项发表于《Nature》（2026 年 10 月 28 日）的工作，由 Ahmad A. Cluntun、Joseph R. Visker、Jesse N. Velasco-Silva、James Carrington、Luis Cedeño-Rosario、Giulia C. Napoli 等完成，颠覆了这一单通道假设。</p><p>关键发现：即使<strong>遗传敲除 MPC</strong>，小鼠心肌仍能氧化<strong>葡萄糖来源的碳</strong>——说明存在一条备用通路，且它<strong>依赖单羧酸转运体 MCT1（Slc16a1）</strong>。进一步，作者发现通常被认为定位于<strong>质膜</strong>的 MCT1，也存在于<strong>小鼠与人心肌细胞的线粒体内膜</strong>：它与基质中的 <strong>LDHB（乳酸脱氢酶 B）<strong>搭档，在</strong>线粒体内部</strong>把<strong>乳酸转成丙酮酸与 NADH</strong>，<strong>直接给电子传递链供料</strong>。关键数字/效应：缺失 MCT1 会损害乳酸氧化、<strong>破坏代谢灵活性</strong>，并在<strong>神经内分泌轴过度激活或缺血—再灌注损伤后加速心衰、增加死亡率</strong>。为什么重要：存在一条<strong>平行于丙酮酸的「乳酸通道」</strong>——糖代谢的瓶颈可能不在丙酮酸，而在一条被长期忽视的乳酸入线粒体通路。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 的能量代谢/心血管条目关联；「冗余通路保证鲁棒性、单点缺失才暴露脆弱性」与 <code>topics/cross-domain-synthesis-2026-q3.md</code> 的「约束-涌现」同构。</p><hr><h3 id="_5-出生前后-大脑「清算」数十亿基因组异常的神经元" tabindex="-1">5. 出生前后，大脑「清算」数十亿基因组异常的神经元 <a class="header-anchor" href="#_5-出生前后-大脑「清算」数十亿基因组异常的神经元" aria-label="Permalink to &quot;5. 出生前后，大脑「清算」数十亿基因组异常的神经元&quot;">​</a></h3><p><strong>原文</strong>：人神经元终末分化、长寿命，对基因剂量极为敏感（CNV 与杂合点突变关联多种神经发育与精神疾病）。作者对胎儿到出生后的人脑做了 2,357 个单神经元全基因组测序，发现产前皮层神经元平均 25.9%（12.7%–46%）携带高度异常的基因组——即涉及多条染色体的广泛 CNV；而出生后这一比例下降约 4.5 倍。携带广泛 CNV 的神经元主要在围产期被淘汰，时间大致与程序性细胞死亡期平行。</p><p><strong>深度扩展</strong>：</p><p>人神经元<strong>终末分化、长寿命</strong>，对基因剂量极为敏感——拷贝数变异（CNV）与杂合点突变被关联到多种神经发育与精神疾病。这项发表于《Nature》（2026 年 10 月 28 日）的工作，由 Diane D. Shao、Yifan Zhao、Joseph Brew、Yahia Adla、Urmi Ghosh、Vinayak V. Viswanadham 等完成，把「大脑基因组质量」这个长期模糊的问题变成了可量化的动态过程。</p><p>方法：对<strong>胎儿到出生后的人脑做了 2,357 个单神经元全基因组测序</strong>（两种 scWGS 方法）。关键数字：<strong>产前皮层神经元平均 25.9%（范围 12.7%–46%）携带高度异常的基因组</strong>——即涉及<strong>多条染色体</strong>的<strong>广泛 CNV</strong>；而<strong>出生后该比例下降约 4.5 倍</strong>（Fisher 合并 P = 3.5×10⁻⁶），说明携带广泛 CNV 的神经元主要在<strong>围产期被淘汰</strong>，时间大致<strong>与程序性细胞死亡期平行</strong>。</p><p>机制线索：对 <strong>44,861 个核</strong>的 snATAC/snRNA 分析显示，<strong>高 CNV 负荷神经元的突触基因表达异常</strong>；存活神经元的 CNV <strong>显著缺失剂量敏感基因与神经发育障碍相关基因</strong>（超几何检验 P&lt;0.05），提示存在<strong>选择性淘汰</strong>——异常的突触基因调控很可能是这些神经元被清除的诱因。为什么重要：<strong>正常大脑的「基因组质量」是在出生前后被主动筛选、而非天生如此</strong>，这为理解神经发育疾病的早期干预窗口提供了新框架。</p><p><strong>跨主题关联</strong>：与 <code>topics/neuroscience/index.md</code>、<code>topics/biomedicine/index.md</code> 的神经发育条目关联；「主动淘汰不合格单元以保系统稳定」与 <code>topics/ai-brain/index.md</code> 中知识网络的「清洗/去噪」逻辑同构。</p><hr><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_6-thinkworld-把「动作思维」写成动力学链-再用世界想象做强化" tabindex="-1">6. ThinkWorld：把「动作思维」写成动力学链，再用世界想象做强化 <a class="header-anchor" href="#_6-thinkworld-把「动作思维」写成动力学链-再用世界想象做强化" aria-label="Permalink to &quot;6. ThinkWorld：把「动作思维」写成动力学链，再用世界想象做强化&quot;">​</a></h3><p><strong>原文</strong>：视觉-语言-动作（VLA）模型在机器人操作上进步快，但泛化受限于带动作标注的机器人演示的多样性与覆盖度；人类视频行为与环境经验更广，从中学习却面临「可扩展数据 vs 显式动作接地」的根本权衡。ThinkWorld 把动作推理扎根于世界动力学，并用世界想象 + 强化学习加以强化：它把每个动作思维表示为动力学链（Chain-of-Dynamics, CoD）——一串离散运动 token，刻画连接「当前世界」与「未来状态」的中间动力学，并作为跨本体的共同动作表示。</p><p><strong>深度扩展</strong>：</p><p>视觉-语言-动作（VLA）模型在机器人操作上进步很快，但泛化受限于<strong>带动作标注的机器人演示</strong>的多样性与覆盖度；人类视频行为与环境经验更广，从中学习却面临「<strong>可扩展数据 vs 显式动作接地</strong>」的根本权衡。这篇 arXiv 预印本（arXiv:2610.37666，2026-10-27；作者 Chaehyun Kim、Chi-Pin Huang、Jisoo Kim、Min-Hung Chen、Yu-Chiang Frank Wang、Seungryong Kim、Fu-En Yang）提出 <strong>ThinkWorld</strong>：把动作推理<strong>扎根于世界动力学</strong>，并用<strong>世界想象 + 强化学习</strong>强化。</p><p>方法：把每个动作思维表示为<strong>动力学链（Chain-of-Dynamics, CoD）</strong>——一串<strong>离散运动 token</strong>，刻画连接「当前世界」与「未来状态」的<strong>中间动力学</strong>，并作为<strong>跨本体的共同动作表示</strong>。训练流程：先用带动作标注的演示<strong>初始化</strong> CoD，再<strong>预测每个 CoD 诱导的未来</strong>、<strong>强化那些预测更贴合观测结果</strong>的 CoD。这样，<strong>无动作标注的视频</strong>也能通过观测到的<strong>状态转移</strong>提供直接监督，让人与机器人经验在<strong>同一推理空间</strong>互相精炼。关键卖点：仿真与真机实验显示有效的<strong>人→机迁移</strong>，以及对未见任务与环境的<strong>强泛化</strong>。为什么重要：它把「离散动作 token」升级为「动力学链」，用<strong>可验证的世界预测</strong>替代稀缺的动作标签——为大规模从视频中学习机器人策略提供了更可扩展的接口。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-system-architecture/index.md</code>、<code>topics/vibe-coding/index.md</code> 的 agent/世界模型条目关联；「用可验证的中间量做监督」与 <code>topics/ai-brain/index.md</code> 的「关联即可用」理念同构。</p>',47)])])}const m=n(e,[["render",a]]);export{l as __pageData,m as default};
